      "card_ids": ["C03"],
      "claim": "LCB01-0371 exhibited absolute oral bioavailability of 99.75% after an 800 mg oral dose compared with IV in subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Tolvaptan had a mean absolute bioavailability of 56% (range 42–80%) after a 30 mg oral tablet versus IV in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Sildenafil had an absolute oral bioavailability of 41% (90% CI 35.6–47.3) after 50 mg oral versus IV administration, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All numeric transferred bioavailability records exceed 20%, with multiple absolute human oral bioavailability values around 41–99.75%. No affirmative low-bioavailability evidence was retrieved.",
  "evidence_gaps": [
    "Molecule 1 groups records for different compounds (brigatinib vs GSK1322322); inconsistent cards were discounted.",
    "Molecule 9 provides only qualitative 'excellent' bioavailability without a numeric threshold-relevant measurement.",
    "No retrieved record affirmatively reports oral bioavailability below 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

